import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;
import java.io.*;
import java.net.InetSocketAddress;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.util.*;
import java.util.concurrent.Executors;

/*
 * College Bus Pass Management System
 * Pure Java web server; HTML and CSS are generated by Java.
 * Requires JDK 17+ (or a JDK that includes jdk.httpserver).
 *
 * Run:
 *   javac CollegeBusPassSystem.java
 *   java CollegeBusPassSystem
 * Open:
 *   http://localhost:8080
 */
public class CollegeBusPassSystem {
    static final List<Student> students = new ArrayList<>();
    static final List<BusRoute> routes = new ArrayList<>();
    static final List<BusPass> passes = new ArrayList<>();
    static int nextPassId = 1001;

    static class Student {
        String id, name, department, year, phone;
        Student(String id, String name, String department, String year, String phone) {
            this.id=id; this.name=name; this.department=department; this.year=year; this.phone=phone;
        }
    }
    static class BusRoute {
        String id, name, from, to, busNumber;
        BusRoute(String id, String name, String from, String to, String busNumber) {
            this.id=id; this.name=name; this.from=from; this.to=to; this.busNumber=busNumber;
        }
    }
    static class BusPass {
        int id; String studentId, routeId; LocalDate startDate, endDate;
        BusPass(int id, String studentId, String routeId, LocalDate startDate, LocalDate endDate) {
            this.id=id; this.studentId=studentId; this.routeId=routeId;
            this.startDate=startDate; this.endDate=endDate;
        }
        String status() {
            LocalDate today = LocalDate.now();
            if (today.isBefore(startDate)) return "NOT STARTED";
            if (today.isAfter(endDate)) return "EXPIRED";
            return "VALID";
        }
    }

    public static void main(String[] args) throws Exception {
        // Small demo records; remove these lines if you want an initially empty system.
        students.add(new Student("STU001", "Ayesha", "AI & DS", "3rd Year", "9876543210"));
        students.add(new Student("STU002", "Rahul", "CSE", "2nd Year", "9876501234"));
        routes.add(new BusRoute("R01", "Gudivada Route", "Gudivada", "College", "AP 16 AB 1234"));
        routes.add(new BusRoute("R02", "Vijayawada Route", "Vijayawada", "College", "AP 16 CD 5678"));

        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/", CollegeBusPassSystem::handle);
        server.setExecutor(Executors.newCachedThreadPool());
        server.start();
        System.out.println("College Bus Pass Management System running at http://localhost:8080");
    }

    static void handle(HttpExchange exchange) throws IOException {
        String path = exchange.getRequestURI().getPath();
        String method = exchange.getRequestMethod();
        Map<String,String> form = method.equalsIgnoreCase("POST") ? readForm(exchange) : new HashMap<>();
        String message = "";

        try {
            if (method.equalsIgnoreCase("POST")) {
                switch (path) {
                    case "/students/add" -> {
                        String id = value(form,"id");
                        if (id.isBlank() || value(form,"name").isBlank()) throw new IllegalArgumentException("Student ID and name are required.");
                        if (students.stream().anyMatch(s -> s.id.equalsIgnoreCase(id))) throw new IllegalArgumentException("Student ID already exists.");
                        students.add(new Student(id, value(form,"name"), value(form,"department"), value(form,"year"), value(form,"phone")));
                        message = "Student added successfully.";
                    }
                    case "/routes/add" -> {
                        String id = value(form,"routeId");
                        if (id.isBlank() || value(form,"from").isBlank() || value(form,"to").isBlank()) throw new IllegalArgumentException("Route ID, starting point and destination are required.");
                        if (routes.stream().anyMatch(r -> r.id.equalsIgnoreCase(id))) throw new IllegalArgumentException("Route ID already exists.");
                        routes.add(new BusRoute(id, value(form,"routeName"), value(form,"from"), value(form,"to"), value(form,"busNumber")));
                        message = "Route added successfully.";
                    }
                    case "/passes/issue" -> {
                        String studentId=value(form,"studentId"), routeId=value(form,"routeId");
                        Student student=findStudent(studentId); BusRoute route=findRoute(routeId);
                        if (student==null || route==null) throw new IllegalArgumentException("Select an existing student and route.");
                        LocalDate start=LocalDate.parse(value(form,"startDate"));
                        LocalDate end=LocalDate.parse(value(form,"endDate"));
                        if (end.isBefore(start)) throw new IllegalArgumentException("End date cannot be before start date.");
                        passes.add(new BusPass(nextPassId++, studentId, routeId, start, end));
                        message = "Bus pass issued successfully.";
                    }
                    default -> message = "Unknown action.";
                }
            }
        } catch (Exception ex) {
            message = ex.getMessage() == null ? "Unable to complete the request." : ex.getMessage();
        }

        String html = page(path, message);
        byte[] bytes = html.getBytes(StandardCharsets.UTF_8);
        exchange.getResponseHeaders().set("Content-Type", "text/html; charset=UTF-8");
        exchange.getResponseHeaders().set("Cache-Control", "no-store");
        exchange.sendResponseHeaders(200, bytes.length);
        try (OutputStream out = exchange.getResponseBody()) { out.write(bytes); }
    }

    static Map<String,String> readForm(HttpExchange ex) throws IOException {
        String body = new String(ex.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
        Map<String,String> result = new HashMap<>();
        for (String pair : body.split("&")) {
            String[] p = pair.split("=", 2);
            String k = URLDecoder.decode(p[0], StandardCharsets.UTF_8);
            String v = p.length > 1 ? URLDecoder.decode(p[1], StandardCharsets.UTF_8) : "";
            result.put(k, v.trim());
        }
        return result;
    }
    static String value(Map<String,String> m, String key) { return m.getOrDefault(key, ""); }
    static Student findStudent(String id) { return students.stream().filter(s -> s.id.equals(id)).findFirst().orElse(null); }
    static BusRoute findRoute(String id) { return routes.stream().filter(r -> r.id.equals(id)).findFirst().orElse(null); }
    static String esc(String s) {
        return s == null ? "" : s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")
                .replace("\"","&quot;").replace("'","&#39;");
    }
    static String page(String path, String message) {
        StringBuilder b = new StringBuilder("""
        <!DOCTYPE html><html lang="en"><head><meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1">
        <title>College Bus Pass Management</title>
        <style>
        *{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f3f6fb;color:#1e293b}
        header{background:#123b66;color:white;padding:22px 5%;}header h1{margin:0;font-size:25px}
        header p{margin:7px 0 0;color:#dbeafe}.layout{display:flex;min-height:calc(100vh - 90px)}
        nav{width:225px;background:#fff;padding:22px 14px;box-shadow:2px 0 10px #00000008}
        nav a{display:block;padding:12px 14px;margin:5px 0;border-radius:8px;color:#334155;text-decoration:none;font-weight:600}
        nav a:hover,nav a.active{background:#e8f1ff;color:#1456a0}
        main{padding:28px;width:100%;max-width:1300px;margin:auto}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:16px;margin-bottom:22px}
        .card,.panel{background:white;border-radius:12px;padding:20px;box-shadow:0 3px 14px #0f172a0b;margin-bottom:20px}
        .card small{color:#64748b}.number{font-size:29px;font-weight:bold;margin-top:8px;color:#164e87}
        h2{margin:0 0 16px;font-size:20px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:14px}
        label{display:block;font-size:13px;font-weight:bold;margin-bottom:6px;color:#475569}
        input,select{width:100%;padding:11px;border:1px solid #cbd5e1;border-radius:7px;font-size:14px;background:white}
        button{border:0;background:#1764ad;color:white;padding:11px 18px;border-radius:7px;font-weight:bold;cursor:pointer;margin-top:14px}
        button:hover{background:#104d88}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:620px}
        th,td{text-align:left;padding:12px;border-bottom:1px solid #e2e8f0;font-size:14px}th{background:#f8fafc;color:#475569}
        .notice{background:#e8f5e9;color:#17632b;padding:12px 15px;border-radius:8px;margin-bottom:18px}
        .status{display:inline-block;padding:5px 9px;border-radius:20px;font-size:11px;font-weight:bold}
        .VALID{background:#dcfce7;color:#166534}.EXPIRED{background:#fee2e2;color:#991b1b}.NOT-STARTED{background:#fef3c7;color:#92400e}
        .muted{color:#64748b;font-size:13px}.empty{color:#64748b;padding:18px;text-align:center}
        @media(max-width:700px){.layout{display:block}nav{width:100%;display:flex;overflow:auto;padding:8px}nav a{white-space:nowrap}main{padding:16px}header h1{font-size:20px}}
        </style></head><body>
        <header><h1>College Bus Pass Management System</h1><p>Transport Office Portal</p></header>
        <div class="layout"><nav>
        """);
        String[][] links={{"/","Dashboard"},{"/students","Students"},{"/routes","Bus Routes"},{"/issue","Issue Pass"},{"/passes","Pass Records"},{"/valid","Valid Passes"}};
        for (String[] link:links) b.append("<a class='").append(path.equals(link[0])?"active":"").append("' href='").append(link[0]).append("'>").append(link[1]).append("</a>");
        b.append("</nav><main>");
        if (!message.isBlank()) b.append("<div class='notice'>").append(esc(message)).append("</div>");
        switch(path) {
            case "/students" -> studentPage(b);
            case "/routes" -> routePage(b);
            case "/issue" -> issuePage(b);
            case "/passes" -> passPage(b, false);
            case "/valid" -> passPage(b, true);
            default -> dashboard(b);
        }
        b.append("</main></div></body></html>");
        return b.toString();
    }

    static void dashboard(StringBuilder b) {
        long valid=passes.stream().filter(p->p.status().equals("VALID")).count();
        long expired=passes.stream().filter(p->p.status().equals("EXPIRED")).count();
        b.append("<h2>Dashboard</h2><div class='cards'>");
        metric(b,"Total Students",students.size()); metric(b,"Total Routes",routes.size());
        metric(b,"Passes Issued",passes.size()); metric(b,"Valid Passes",valid); metric(b,"Expired Passes",expired);
        b.append("</div><div class='panel'><h2>Welcome to the Transport Office</h2><p class='muted'>Use the menu to register students, manage routes, issue bus passes and check pass validity.</p><p><b>Validity rule:</b> A pass is valid from its start date through its end date. After the end date, its status automatically becomes EXPIRED.</p></div>");
        b.append("<div class='panel'><h2>Recent Pass Records</h2>"); passTable(b, passes.stream().sorted((a,c)->Integer.compare(c.id,a.id)).limit(5).toList()); b.append("</div>");
    }
    static void metric(StringBuilder b,String label,long n){b.append("<div class='card'><small>").append(label).append("</small><div class='number'>").append(n).append("</div></div>");}

    static void studentPage(StringBuilder b) {
        b.append("<h2>Student Management</h2><div class='panel'><h2>Add Student</h2><form method='post' action='/students/add'><div class='grid'>");
        field(b,"Student ID","id","e.g. STU003"); field(b,"Full Name","name","Student name");
        field(b,"Department","department","e.g. AI & DS"); field(b,"Year","year","e.g. 3rd Year"); field(b,"Phone","phone","Mobile number");
        b.append("</div><button type='submit'>Add Student</button></form></div><div class='panel'><h2>Student List</h2><div class='table-wrap'><table><tr><th>ID</th><th>Name</th><th>Department</th><th>Year</th><th>Phone</th></tr>");
        if(students.isEmpty()) b.append("<tr><td colspan='5' class='empty'>No students added.</td></tr>");
        for(Student s:students)b.append("<tr><td>").append(esc(s.id)).append("</td><td>").append(esc(s.name)).append("</td><td>").append(esc(s.department)).append("</td><td>").append(esc(s.year)).append("</td><td>").append(esc(s.phone)).append("</td></tr>");
        b.append("</table></div></div>");
    }
    static void routePage(StringBuilder b) {
        b.append("<h2>Bus Route Management</h2><div class='panel'><h2>Add Route</h2><form method='post' action='/routes/add'><div class='grid'>");
        field(b,"Route ID","routeId","e.g. R03"); field(b,"Route Name","routeName","e.g. Town Route");
        field(b,"Starting Point","from","Starting location"); field(b,"Destination","to","College"); field(b,"Bus Number","busNumber","Vehicle number");
        b.append("</div><button type='submit'>Add Route</button></form></div><div class='panel'><h2>Route List</h2><div class='table-wrap'><table><tr><th>Route ID</th><th>Route Name</th><th>From</th><th>To</th><th>Bus Number</th></tr>");
        if(routes.isEmpty()) b.append("<tr><td colspan='5' class='empty'>No routes added.</td></tr>");
        for(BusRoute r:routes)b.append("<tr><td>").append(esc(r.id)).append("</td><td>").append(esc(r.name)).append("</td><td>").append(esc(r.from)).append("</td><td>").append(esc(r.to)).append("</td><td>").append(esc(r.busNumber)).append("</td></tr>");
        b.append("</table></div></div>");
    }
    static void issuePage(StringBuilder b) {
        b.append("<h2>Issue Bus Pass</h2><div class='panel'><form method='post' action='/passes/issue'><div class='grid'><div><label>Student</label><select name='studentId' required><option value=''>Select student</option>");
        for(Student s:students)b.append("<option value='").append(esc(s.id)).append("'>").append(esc(s.id+" - "+s.name)).append("</option>");
        b.append("</select></div><div><label>Bus Route</label><select name='routeId' required><option value=''>Select route</option>");
        for(BusRoute r:routes)b.append("<option value='").append(esc(r.id)).append("'>").append(esc(r.id+" - "+r.name+" ("+r.from+" to "+r.to+")")).append("</option>");
        b.append("</select></div><div><label>Start Date</label><input type='date' name='startDate' required></div><div><label>End Date</label><input type='date' name='endDate' required></div></div><button type='submit'>Issue Pass</button></form></div>");
        if(students.isEmpty()||routes.isEmpty()) b.append("<p class='muted'>Add at least one student and one route before issuing a pass.</p>");
    }
    static void passPage(StringBuilder b, boolean onlyValid) {
        b.append("<h2>").append(onlyValid?"Valid Bus Passes":"Issued Pass Records").append("</h2><div class='panel'><p class='muted'>Status is calculated automatically from today's date: ").append(LocalDate.now()).append(".</p>");
        List<BusPass> shown=passes.stream().filter(p->!onlyValid||p.status().equals("VALID")).toList();
        passTable(b,shown); b.append("</div>");
    }
    static void passTable(StringBuilder b,List<BusPass> list) {
        b.append("<div class='table-wrap'><table><tr><th>Pass ID</th><th>Student</th><th>Route</th><th>Start Date</th><th>End Date</th><th>Status</th></tr>");
        if(list.isEmpty()) b.append("<tr><td colspan='6' class='empty'>No pass records found.</td></tr>");
        for(BusPass p:list) {
            Student s=findStudent(p.studentId); BusRoute r=findRoute(p.routeId); String status=p.status();
            b.append("<tr><td>BP").append(p.id).append("</td><td>").append(s==null?"-":esc(s.name)+" ("+esc(s.id)+")")
             .append("</td><td>").append(r==null?"-":esc(r.name)).append("</td><td>").append(p.startDate)
             .append("</td><td>").append(p.endDate).append("</td><td><span class='status ").append(status.replace(" ","-")).append("'>").append(status).append("</span></td></tr>");
        }
        b.append("</table></div>");
    }
    static void field(StringBuilder b,String label,String name,String placeholder) {
        b.append("<div><label>").append(label).append("</label><input name='").append(name).append("' placeholder='").append(placeholder).append("' required></div>");
    }
}
